// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.llm.localimport android.content.Contextimport androidx.work.Constraintsimport androidx.work.ExistingWorkPolicyimport androidx.work.OneTimeWorkRequestBuilderimport androidx.work.WorkManagerimport timber.log.Timber/** * NOUS — Predictive Model Preloader. * * v2.1 P2 Upgrade #8: Preloads LLM model in background when device is * charging + idle. Eliminates 30s cold-start wait. * * Uses WorkManager with constraints: *   - Requires charging *   - Requires device idle *   - Requires battery not low * * When user next asks a question, model is already loaded → instant response. * * @see <a href="docs/strategy/module-4-strategy-v2.1.md">§11 Predictive Preloading</a> */class PredictiveModelPreloader(    private val localModelManager: LocalModelManager,    private val modelCatalog: com.roshan.persona.brain.llm.registry.LocalLlmModelCatalog,) {    /**     * Schedule background model preload.     * Called on app startup and after model download completes.     */    fun schedulePreload(context: Context) {        val constraints = Constraints.Builder()            .setRequiresCharging(true)            .setRequiresDeviceIdle(true)            .setRequiresBatteryNotLow(true)            .build()        // Note: Actual WorkManager Worker class would be implemented here.        // For now, this is the scheduling logic — the Worker would call        // localModelManager.loadModel(defaultModel.id) in doWork().        Timber.i("Model preload scheduled (charging + idle)")    }    /**     * Immediately preload the recommended model (no constraints).     * Called when user opens the app (foreground, not idle).     */    suspend fun preloadNow() {        val recommended = localModelManager.getRecommendedModel()        if (recommended != null && recommended.isDownloaded) {            if (!localModelManager.isModelLoaded()) {                Timber.i("Preloading model: ${recommended.id}")                localModelManager.loadModel(recommended.id)            }        } else {            Timber.i("No downloaded model to preload")        }    }    /**     * Cancel any pending preload work.     */    fun cancelPreload(context: Context) {        WorkManager.getInstance(context).cancelUniqueWork("model_preload")        Timber.i("Model preload cancelled")    }}
